dtsPropsFor.Ico:
/** qual desenho — cai em 'baixar' se o nome nao existir */
nome: 'ampulheta' | 'apagar' | 'audio_m4a' | 'audio_wav' | 'aviso' | 'baixar' | 'buscar' | 'caixa' | 'calendario' | 'certo' | 'copiar' | 'estrela' | 'estrelaCheia' | 'fast' | 'livroReg' | 'lixeira' | 'music' | 'pasta' | 'playlist' | 'rapido' | 'renomear' | 'sair' | 'studio' | 'tempo' | 'tocar' | 'video';
/** lado do quadrado, em px (padrao 20) */
tamanho?: number;

dtsPropsFor.Omnitrix:
/** false deixa a roda apagada, sem vigiar a area de transferencia */
ligado?: boolean;
/** chamado com o formato escolhido na coroa */
onEscolher?: (formato: string) => void;

dtsPropsFor.ConfirmDialog:
/** nada aparece enquanto for false */
open?: boolean;
title?: string;
message?: string;
/** itens listados sob a mensagem (ex: os arquivos que serao apagados) */
list?: string[];
/** letra miuda embaixo, pra consequencia que nao cabe na mensagem */
note?: string;
/** caixa de marcar opcional: { label, checked, onChange } */
checkbox?: { label: string; checked: boolean; onChange: (v: boolean) => void };
confirmLabel?: string;
cancelLabel?: string;
/** true pinta o botao de confirmar como destrutivo */
danger?: boolean;
onConfirm?: () => void;
onCancel?: () => void;

dtsPropsFor.BatchActionsDialog:
open?: boolean;
/** quantos itens estao marcados */
count?: number;
onClose?: () => void;
onDelete?: () => void;
onShare?: () => void;

dtsPropsFor.PeriodPickerModal:
/** o acervo. O campo de data e `timestamp` (ms) -- nao `createdAt`:
 *  a peca so oferece os periodos que EXISTEM aqui dentro, entao com o
 *  nome errado ela abre vazia dizendo "Nada registrado". */
history?: Array<{ id?: string; timestamp: number }>;
/** periodo que ja estava escolhido */
initial?: unknown;
onApply?: (periodo: unknown) => void;
onClose?: () => void;
